<?php
require getcwd().'/vendor/autoload.php';$app=require getcwd().'/bootstrap/app.php';$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
use App\Models\{Tenant,User,ConversationSetting,AgentEnrollment};use App\Tenancy\TenantContext;use Illuminate\Support\Facades\{DB,Hash};use Illuminate\Support\Str;
