$c=app(TenantContext::class);try{$c->apply(platform:true);$t=Tenant::create(['name'=>'RECOVERY-6 lab','slug'=>'recovery6-lab','status'=>'active']);$password=bin2hex(random_bytes(24));$u=new User;$u->forceFill(['name'=>'Lab operator','email'=>'conversation-lab@example.invalid','password'=>Hash::make($password),'tenant_id'=>$t->id,'role'=>'tenant_admin','status'=>'active','must_change_password'=>false])->save();$c->forUser($u);app(App\Diagnostics\Catalog::class)->ensure();$setting=new ConversationSetting;$setting->forceFill(['tenant_id'=>$t->id,'enabled'=>true,'updated_by'=>$u->id,'retention_days'=>30])->save();$id=(string)Str::uuid();$code=$id.'.'.bin2hex(random_bytes(32));$e=new AgentEnrollment;$e->forceFill(['id'=>$id,'tenant_id'=>$t->id,'name'=>'Conversation lab Agent','created_by'=>$u->id,'secret_hash'=>hash('sha256',$code),'expires_at'=>now()->addMinutes(30)])->save();echo json_encode(['email'=>$u->email,'password'=>$password,'code'=>$code,'tenant_id'=>$t->id,'user_id'=>$u->id],JSON_THROW_ON_ERROR);}finally{$c->apply();}
